/* Ponto de partida da varredura.

   id_from=0 é de propósito: a carga histórica não tem data de corte, ela vai
   do primeiro pedido que existe até o último. */
return [{ json: { proximoId: 0, pagina: 0 } }];

/* Uma página da Base vira registros do LiveOps.

   ── Por que esta carga NÃO usa filter_order_source ──────────────────
   O fluxo de todo dia filtra a origem no servidor, e faz bem: economiza
   tráfego. Aqui é o contrário — a varredura lê TUDO e separa o WhatsApp
   aqui dentro, por dois motivos:

   1. Se o id da origem estiver errado, o filtro do servidor devolve lista
      vazia sem erro nenhum, e a carga terminaria "com sucesso" tendo
      importado zero. Lendo tudo, isso é impossível de acontecer calado.

   2. Lendo tudo dá para ver o NOME que a Base usa em cada origem, no log do
      fim. Foi assim que se descobriu que "WhatsApp" chega como personal/0.

   ── O que esta carga NÃO alcança ────────────────────────────────────
   A Base arquiva pedido depois de 90 dias, e o getOrders não devolve
   arquivado — medido em 22/08/2026: o mais antigo que ela entrega é de
   24/05/2026, e pedir com date_from de janeiro devolve o mesmo pedido de
   maio. Não é parâmetro faltando, é limite da conta.

   Uma versão anterior deste código tentava medir o Arquivo contando os ids
   que faltavam na sequência. Não serve: os order_id da BaseLinker são
   globais, de todos os clientes dela. Nesta conta o pedido mais antigo tem
   id 36 milhões e os recentes passam de 47 milhões — os 11 milhões de
   "buracos" são pedidos de outras empresas, não Arquivo. A conta foi
   removida para ninguém decidir nada em cima dela. */

const r = $json || {};
if (r.status && r.status !== 'SUCCESS') {
  throw new Error('A Base recusou: ' + (r.error_message || r.error_code || JSON.stringify(r).slice(0,200)));
}
const pedidos = r.orders || [];

/* Página vazia = acabou. Devolver zero itens encerra o laço sozinho: sem
   item, nada segue para o nó seguinte e a repetição para. */
const estado = $getWorkflowStaticData('global');
if (!estado.iniciado) {
  estado.iniciado = true;
  estado.lidos = 0; estado.gravados = 0; estado.paginas = 0;
  estado.dataMaisAntiga = null;
  estado.porOrigem = {};
}

if (!pedidos.length) {
  console.log('── Carga histórica terminada ──');
  console.log(estado.paginas + ' página(s) · ' + estado.lidos + ' pedido(s) lidos · ' +
              estado.gravados + ' do WhatsApp gravados');
  console.log('pedido mais antigo alcançado: ' + (estado.dataMaisAntiga || '—') +
              '  (a Base arquiva depois de 90 dias e não devolve arquivado)');
  const origens = Object.keys(estado.porOrigem).sort((a,b)=>estado.porOrigem[b]-estado.porOrigem[a]);
  console.log('origens encontradas: ' + origens.map(k=>k+'='+estado.porOrigem[k]).join(' · '));
  return [];
}

const TZ = 'America/Sao_Paulo';
function data(ts){
  if(!ts) return '';
  return new Intl.DateTimeFormat('sv-SE',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'})
    .format(new Date(Number(ts)*1000));
}
function hora(ts){
  if(!ts) return '';
  return new Intl.DateTimeFormat('pt-BR',{timeZone:TZ,hour:'2-digit',minute:'2-digit'})
    .format(new Date(Number(ts)*1000));
}
/* O total não vem pronto: a Base entrega os produtos e o frete separados.
   Somar aqui evita que a tela mostre um valor diferente do que a Base
   mostra — a divergência que ninguém consegue explicar depois. */
function total(p){
  const itens=(p.products||[]).reduce((a,i)=>a+(Number(i.price_brutto)||0)*(Number(i.quantity)||0),0);
  return Math.round((itens+(Number(p.delivery_price)||0))*100)/100;
}

const nomeStatus = $('Status da Base').first().json.statuses
  ? Object.fromEntries(($('Status da Base').first().json.statuses||[]).map(s=>[String(s.id), s.name]))
  : {};
const jaTemos = $('O que já temos').first().json || {};
const carimbo = new Date().toLocaleString('pt-BR',{timeZone:TZ});

/* Só o que entrou pelo WhatsApp. A Base marca isso em order_source, e o
   nome varia conforme o cadastro da conta — por isso a comparação é por
   pedaço do texto, e não igualdade exata. */
function ehWhatsApp(p){
  const fonte = String(p.order_source || '').toLowerCase();
  const nome  = String(p.order_source_info || '').toLowerCase();
  return fonte.includes('whats') || nome.includes('whats')
      || (fonte === 'personal' && Number(p.order_source_id) === 0);
}

const patch = {};
let maior = 0, gravadosAqui = 0;

pedidos.forEach(p => {
  const id = Number(p.order_id) || 0;
  if (id > maior) maior = id;
  estado.lidos++;
  const dia = data(p.date_add || p.date_confirmed || 0);
  if (dia && (!estado.dataMaisAntiga || dia < estado.dataMaisAntiga)) estado.dataMaisAntiga = dia;
  const chaveOrigem = (p.order_source || '?') + '/' + (p.order_source_id === undefined ? '?' : p.order_source_id);
  estado.porOrigem[chaveOrigem] = (estado.porOrigem[chaveOrigem] || 0) + 1;

  if (!ehWhatsApp(p)) return;

  const quando = p.date_add || p.date_confirmed || 0;
  const registro = {
    id: 'base_' + p.order_id,
    numero: String(p.order_id),
    externo: String(p.external_order_id || p.shop_order_id || ''),
    cliente: p.delivery_fullname || p.invoice_fullname || p.user_login || '',
    telefone: String(p.phone || '').replace(/\D/g, ''),
    cpf: String(p.invoice_nip || '').replace(/\D/g, ''),
    email: String(p.email || ''),
    valor: total(p),
    itens: (p.products || []).reduce((a, i) => a + (Number(i.quantity) || 0), 0),
    status: nomeStatus[String(p.order_status_id)] || ('status ' + p.order_status_id),
    canal: 'WhatsApp',
    data: data(quando),
    hora: hora(quando),
    link: 'https://panel-u.baselinker.com/orders.php#order:' + p.order_id,
    sincronizadoEm: carimbo,
    _by: 'n8n'
  };

  /* Pedido que já está igual no LiveOps não é regravado. Numa carga de
     milhares isso é a diferença entre alguns minutos e uma hora — e evita
     que a tela de quem estiver trabalhando pisque a cada página. */
  const atual = jaTemos['base_' + p.order_id];
  if (atual) {
    const iguais = Object.keys(registro).every(k => k === 'sincronizadoEm' || String(atual[k] || '') === String(registro[k] || ''));
    if (iguais) return;
  }
  patch['base_' + p.order_id] = registro;
  gravadosAqui++;
  estado.gravados++;
});

estado.paginas++;
console.log('página ' + estado.paginas + ': ' + pedidos.length + ' pedido(s) · ' +
            gravadosAqui + ' para gravar · próximo id ' + (maior + 1));

return [{ json: { patch, proximoId: maior + 1, quantos: pedidos.length } }];
